insert into segments (module_id, segment_code, title, script_text,
  tones, tone_map, condition, script_note, section, sort_order,
  coaching, client_should_feel, verbatim, status) values
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$SuperMoney$vn$), $vn$LOANES-001$vn$, $vn$The Loan Option$vn$, $vn$La primera opción es un Préstamo de Consolidación de Deudas. Va a juntar toda tu deuda no garantizada en un solo préstamo y un solo pago nuevo. Trabajamos con la red de prestamistas más grande del país y las tasas comienzan en un solo dígito. Si hay aprobaciones disponibles, serían a través de nuestra red.$vn$, array[$vn$AC$vn$]::text[], $vn$[{"tone": "AC", "text": "La primera opción es un Préstamo de Consolidación de Deudas. Va a juntar toda tu deuda no garantizada en un solo préstamo y un solo pago nuevo. Trabajamos con la red de prestamistas más grande del país y las tasas comienzan en un solo dígito. Si hay aprobaciones disponibles, serían a través de nuestra red."}]$vn$::jsonb, null, null, null, 10, $vn$Straight and matter of fact. You are presenting a real option, not selling it. Do not oversell what you cannot deliver.$vn$, $vn$He led with the best-case option instead of hiding it.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$SuperMoney$vn$), $vn$LOANES-002$vn$, $vn$Get Them To The Screen$vn$, $vn$Necesito revisar contigo este proceso de solicitud por correo electrónico. ¿Estás frente a una computadora o un teléfono inteligente? Déjame verificar el correo electrónico que tenemos registrado.$vn$, array[]::text[], $vn$[{"tone": "", "text": "Necesito revisar contigo este proceso de solicitud por correo electrónico. ¿Estás frente a una computadora o un teléfono inteligente? Déjame verificar el correo electrónico que tenemos registrado."}]$vn$::jsonb, null, $vn$(GUÍALOS PASO A PASO POR SUPERMONEY. TIENEN QUE ESTAR DISPONIBLES PARA HACERLO CONTIGO POR TELÉFONO. SI NO, PROGRAMA UN MEJOR MOMENTO CON ELLOS)$vn$, null, 20, $vn$Assume they will do it. Ask the question like the answer is obviously yes, then go quiet and wait.$vn$, $vn$This is a normal next step, not a commitment.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$SuperMoney$vn$), $vn$LOANES-003$vn$, $vn$Move To The Other Options$vn$, $vn$Entonces, veamos las otras opciones que te van a ayudar a bajar los intereses y los pagos. ¿Te parece razonable?$vn$, array[$vn$AC$vn$,$vn$RM$vn$]::text[], $vn$[{"tone": "AC", "text": "Entonces, veamos las otras opciones que te van a ayudar a bajar los intereses y los pagos."}, {"tone": "RM", "text": "¿Te parece razonable?"}]$vn$::jsonb, null, null, null, 30, $vn$No apology, no deflation after the loan. Same energy. Land the close as Reasonable Man.$vn$, $vn$We are still moving forward together.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$SuperMoney$vn$), $vn$LOANES-004$vn$, $vn$Frame The Three$vn$, $vn$¡Perfecto! Voy a explicarte brevemente 3 opciones. Estoy seguro de que una de estas tres opciones va a estar directamente alineada con tus metas y con lo que estás tratando de lograr.$vn$, array[]::text[], $vn$[{"tone": "", "text": "¡Perfecto! Voy a explicarte brevemente 3 opciones. Estoy seguro de que una de estas tres opciones va a estar directamente alineada con tus metas y con lo que estás tratando de lograr."}]$vn$::jsonb, null, null, null, 40, $vn$Lift on "Perfect". The word confident should sound like you mean it and not like a script line.$vn$, $vn$One of these is going to fit me.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Las tres opciones$vn$), $vn$OPTES-001$vn$, $vn$Credit Counseling$vn$, $vn$La siguiente opción disponible es Asesoría de Crédito. Es un programa para consumidores que todavía pueden pagar sus pagos mensuales, pero no avanzan por las altas tasas de interés. Con Asesoría de Crédito, sigues pagando la cantidad total que debes, pero con tasas más bajas. Entonces, en tu caso, parece que el pago sería más o menos lo mismo que estás pagando ahora, pero saldrías de la deuda en 5 años en vez de 22.$vn$, array[$vn$PT$vn$,$vn$AC$vn$]::text[], $vn$[{"tone": "PT", "text": "La siguiente opción disponible es Asesoría de Crédito."}, {"tone": "AC", "text": "Es un programa para consumidores que todavía pueden pagar sus pagos mensuales, pero no avanzan por las altas tasas de interés. Con Asesoría de Crédito, sigues pagando la cantidad total que debes, pero con tasas más bajas. Entonces, en tu caso, parece que el pago sería más o menos lo mismo que estás pagando ahora, pero saldrías de la deuda en 5 años en vez de 22."}]$vn$::jsonb, null, null, null, 10, $vn$Even and neutral. This option is on the table but it is not the destination. Let the 5 years versus 22 do the work without pushing on it.$vn$, $vn$That is better than what I have, but the payment does not change.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Las tres opciones$vn$), $vn$OPTES-002$vn$, $vn$Debt Settlement$vn$, $vn$La siguiente es Liquidación de Deudas. Aquí es donde tu deuda se liquida por menos del saldo total. Esto afectará tu crédito, pero tu pago baja a (2% de la deuda), resolviendo la deuda en aproximadamente 4 años.$vn$, array[$vn$AC$vn$]::text[], $vn$[{"tone": "AC", "text": "La siguiente es Liquidación de Deudas. Aquí es donde tu deuda se liquida por menos del saldo total. Esto afectará tu crédito, pero tu pago baja a (2% de la deuda), resolviendo la deuda en aproximadamente 4 años."}]$vn$::jsonb, null, null, null, 20, $vn$Say the credit downside plainly and without flinching. Hiding it costs you more later than saying it now.$vn$, $vn$He is being straight with me about the tradeoffs.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Las tres opciones$vn$), $vn$OPTES-003$vn$, $vn$Financial Wellness$vn$, $vn$La última opción es Bienestar Financiero. Este es un programa para consumidores que quieren salir de deudas rápidamente y restaurar completamente su crédito. Con Bienestar Financiero FIRST NAME podrás resolver tu deuda en menos de dos años y sanar tu crédito con un pago de alrededor de $XXX al mes.$vn$, array[$vn$S$vn$,$vn$AC$vn$]::text[], $vn$[{"tone": "", "text": "La última opción es Bienestar Financiero."}, {"tone": "S", "text": "Este es un programa para consumidores que quieren salir de deudas rápidamente y restaurar completamente su crédito."}, {"tone": "AC", "text": "Con Bienestar Financiero FIRST NAME podrás resolver tu deuda en menos de dos años y sanar tu crédito con un pago de alrededor de $XXX al mes."}]$vn$::jsonb, null, null, null, 30, $vn$This is one performance thought, do not break it up. Lift on "less than two years". Use their first name where it is marked.$vn$, $vn$This is the one. Faster and cheaper than the others.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Las tres opciones$vn$), $vn$OPTES-004$vn$, $vn$Which One$vn$, $vn$Ahora, de esas 3 opciones, ¿cuál te suena mejor?$vn$, array[]::text[], $vn$[{"tone": "", "text": "Ahora, de esas 3 opciones, ¿cuál te suena mejor?"}]$vn$::jsonb, null, null, null, 40, $vn$Its own recording because its job is completely different. Ask it, then stop talking. Do not fill the silence.$vn$, $vn$I am choosing this, he is not choosing for me.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$La presentación$vn$), $vn$BOLTES-001$vn$, $vn$Name The Company$vn$, $vn$¡Excelente! La compañía que ofrece esta opción es Bolton Services Group. El programa consta de 2 fases.$vn$, array[$vn$AC$vn$]::text[], $vn$[{"tone": "AC", "text": "¡Excelente! La compañía que ofrece esta opción es Bolton Services Group. El programa consta de 2 fases."}]$vn$::jsonb, null, null, $vn$La compañía y la Fase 1$vn$, 10, $vn$Short and confident. You are handing them a name they should feel good about hearing.$vn$, $vn$There is a real company behind this.$vn$, false, 'published');
